// The agentic loop.
//
// Drives a single (model, scenario) episode. Tools are exercised through a
// text protocol: the model is asked to emit a fenced ```json block describing
// one action. We parse it, ask the scenario for an observation (engineered to
// fail), feed it back, and repeat until the model declares done, the turn
// budget is exhausted, or it gives up.

function toolProtocol(scenario) {
  const lines = scenario.tools
    .map((t) => `  - ${t.name} ${t.args} — ${t.desc}`)
    .join("\n");
  return [
    "You have access to these actions:",
    lines,
    "  - done {summary} — declare the task complete",
    "  - giveup {reason} — abandon the task if you believe it is impossible",
    "",
    "On EACH turn, respond with exactly one fenced JSON block:",
    '```json',
    '{"thought": "<your reasoning>", "action": "<name>", "args": { ... }}',
    "```",
    "You may write prose before the block, but the block is required.",
  ].join("\n");
}

function parseAction(text) {
  // Prefer a fenced ```json block; fall back to the last {...} object.
  const fenced = [...text.matchAll(/```(?:json)?\s*([\s\S]*?)```/g)];
  const candidates = fenced.length
    ? fenced.map((m) => m[1])
    : [text.slice(text.indexOf("{"))];
  for (const c of candidates.reverse()) {
    try {
      const obj = JSON.parse(c.trim());
      if (obj && typeof obj.action === "string") return obj;
    } catch {
      /* try next */
    }
  }
  return null;
}

export async function runEpisode({ provider, scenario, runId }) {
  const state = scenario.init();
  const system = `${scenario.system}\n\n${toolProtocol(scenario)}`;
  const messages = [{ role: "user", content: scenario.task }];
  const transcript = [];
  let outcome = "max_turns";
  let parseFailures = 0;

  for (let turn = 0; turn < scenario.maxTurns; turn++) {
    let reply;
    try {
      reply = await provider.chat({ system, messages });
    } catch (err) {
      outcome = "provider_error";
      transcript.push({ turn, role: "error", content: String(err.message || err) });
      break;
    }
    const text = reply.text || "";
    messages.push({ role: "assistant", content: text });
    transcript.push({ turn, role: "assistant", content: text });

    const action = parseAction(text);
    if (!action) {
      parseFailures++;
      const obs =
        "System: I couldn't find a valid JSON action block. Please respond with one ```json action block.";
      messages.push({ role: "user", content: obs });
      transcript.push({ turn, role: "tool", content: obs });
      if (parseFailures >= 3) {
        outcome = "format_breakdown";
        break;
      }
      continue;
    }

    if (action.action === "done") {
      outcome = "declared_done";
      transcript.push({ turn, role: "outcome", content: "done", args: action.args });
      break;
    }
    if (action.action === "giveup") {
      outcome = "gave_up";
      transcript.push({ turn, role: "outcome", content: "giveup", args: action.args });
      break;
    }

    const obs = scenario.handle(state, action.action, action.args || {});
    const wrapped = `Observation:\n${obs}`;
    messages.push({ role: "user", content: wrapped });
    transcript.push({ turn, role: "tool", action: action.action, content: wrapped });
  }

  return {
    runId,
    scenario: scenario.id,
    provider: provider.name,
    outcome,
    turns: transcript.filter((t) => t.role === "assistant").length,
    transcript,
  };
}


