// Provider abstraction.
//
// Every provider exposes a single async method:
//   chat({ system, messages }) -> { text, usage }
// where messages is [{ role: 'user'|'assistant', content: string }].
//
// This deliberately avoids per-provider function-calling schemas. The agent
// loop (src/agent.js) drives tools through a text protocol instead, so adding a
// new model only requires a thin chat() wrapper.

import { readFileSync, existsSync } from "node:fs";

// --- tiny .env loader (no dependency) ---
export function loadEnv(path = ".env") {
  if (!existsSync(path)) return;
  for (const line of readFileSync(path, "utf8").split("\n")) {
    const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/);
    if (!m) continue;
    const [, k, v] = m;
    if (!(k in process.env) || process.env[k] === "") {
      process.env[k] = v.replace(/^["']|["']$/g, "");
    }
  }
}

async function withRetry(fn, { tries = 4, base = 800, label = "request" } = {}) {
  let lastErr;
  for (let i = 0; i < tries; i++) {
    try {
      return await fn();
    } catch (err) {
      lastErr = err;
      const retryable =
        err.status === 429 || (err.status >= 500 && err.status < 600) ||
        err.code === "ETIMEDOUT" || err.code === "ECONNRESET";
      if (!retryable || i === tries - 1) break;
      const wait = base * 2 ** i + Math.floor(Math.random() * 250);
      await new Promise((r) => setTimeout(r, wait));
    }
  }
  throw new Error(`${label} failed: ${lastErr?.message || lastErr}`);
}

function httpError(status, body) {
  const e = new Error(`HTTP ${status}: ${String(body).slice(0, 400)}`);
  e.status = status;
  return e;
}

// --- Gemini (Google Generative Language API) ---
