#!/usr/bin/env node
// Pretty-print a single episode transcript from a ranked.json file.
//
// Usage:
//   node src/report.js results/<dir>/ranked.json              # show #1 (most severe)
//   node src/report.js results/<dir>/ranked.json 3            # show 4th
//   node src/report.js results/<dir>/ranked.json impossible-test#7   # by runId

import { readFileSync } from "node:fs";

const [file, sel] = process.argv.slice(2);
if (!file) {
  console.error("usage: node src/report.js <ranked.json> [index|runId]");
  process.exit(1);
}
const ranked = JSON.parse(readFileSync(file, "utf8"));
let ep;
if (!sel) ep = ranked[0];
else if (/^\d+$/.test(sel)) ep = ranked[parseInt(sel, 10)];
else ep = ranked.find((r) => r.runId === sel);
if (!ep) {
  console.error("episode not found");
  process.exit(1);
}

const C = { dim: "\x1b[2m", asst: "\x1b[36m", env: "\x1b[33m", out: "\x1b[35m", r: "\x1b[0m" };
console.log(`${C.dim}runId:${C.r} ${ep.runId}   ${C.dim}subject:${C.r} ${ep.provider}`);
console.log(`${C.dim}outcome:${C.r} ${ep.outcome}   ${C.dim}heuristic:${C.r} ${ep.heuristic?.score}`);
if (ep.judge)
  console.log(
    `${C.dim}judge:${C.r} severity=${ep.judge.severity} trajectory=${ep.judge.trajectory} tags=[${(ep.judge.tags || []).join(", ")}]`
  );
console.log("─".repeat(70));
for (const t of ep.transcript) {
  if (t.role === "assistant") console.log(`${C.asst}ASSISTANT${C.r}\n${t.content}\n`);
  else if (t.role === "tool") console.log(`${C.env}${t.content}${C.r}\n`);
  else if (t.role === "outcome") console.log(`${C.out}[${t.content} ${JSON.stringify(t.args || {})}]${C.r}\n`);
  else if (t.role === "error") console.log(`${C.out}[error: ${t.content}]${C.r}\n`);
}


